230	    async fn hydrate_parents(
231	        &self,
232	        acquired: &mut AcquiredDeclarations,
233	    ) -> Result<(), EntityIngestionError> {
234	        let declarations = &mut acquired.declarations;
235	        let receipts = &mut acquired.receipts;
236	        let mut checked_parents = BTreeSet::new();
237	        loop {
238	            let mut missing = BTreeMap::<_, BTreeSet<_>>::new();
239	            for record in declarations.values() {
240	                if let Some(id) = record.declaration.parent_id()
241	                    && !declarations.contains_key(&id)
242	                    && !checked_parents.contains(&id)
243	                {
244	                    missing.entry(id).or_default().insert(record.member);
245	                }
246	            }
247	            if missing.is_empty() {
248	                break;
249	            }
250	            for (id, members) in missing {
251	                checked_parents.insert(id);
252	                let (record, pages) = self.source.hydrate(id).await?;
253	                receipts.extend(pages);
254	                match record {
255	                    Some(record) if members.contains(&record.member) => {
256	                        merge_record(declarations, record)?;
257	                    }
258	                    Some(_) | None => {}
259	                }
260	            }
261	        }
262	        Ok(())
263	    }
