179	fn decode_source(source: Value, fetched_at: DateTime<Utc>) -> Result<DecodedDeclaration, ApiError> {
180	    let source_json = source.to_string();
181	    let source: Interest = serde_json::from_value(source)?;
182	    let (version_index, latest) = source
183	        .versions
184	        .into_iter()
185	        .enumerate()
186	        .max_by_key(|(_, version)| (version.register.published_date, version.register.id))
187	        .ok_or_else(|| ApiError::ResponseError("declaration has no published version".into()))?;
188	    let pointer = format!("/versions/{version_index}/fields");
189	    let fields = latest.fields.unwrap_or_default();
190	    let mut funding = Vec::new();
191	    let mut pointers = Vec::new();
192	    funding_entries(&fields, &pointer, &mut funding, &mut pointers)?;
193	    let declaration = CapturedDeclaration::new(
194	        DeclarationId::new(source.id)?,
195	        source
196	            .parent_interest_id
197	            .map(DeclarationId::new)
198	            .transpose()?,
199	        source.category.id,
200	        source.category.name,
201	        latest.register.id,
202	        latest.register.published_date,
203	        latest.registration_date,
204	        funding,
205	        fetched_at,
206	        source_json,
207	    )?;
208	    Ok(DecodedDeclaration {
209	        declaration,
210	        fields,
211	        source_pointer: pointer,
212	        funding_source_pointers: pointers,
213	    })
214	}
