   158	    async fn acquire(
   159	        &self,
   160	        mode: DeclarationSyncMode,
   161	        scope: &[MemberId],
   162	        window: &DiscoveryWindow,
   163	        mut declarations: BTreeMap<DeclarationId, OwnedDeclaration>,
   164	    ) -> Result<AcquiredDeclarations, EntityIngestionError> {
   165	        let mut receipts = Vec::new();
   166	        let mut exclusions = BTreeMap::new();
   167	        let mut omissions = Vec::new();
   168	        match mode {
   169	            DeclarationSyncMode::Daily => {
   170	                let (discovered, pages) = self.source.discover(window).await?;
   171	                receipts.extend(pages);
   172	                for (id, owner) in discovered {
   173	                    if declarations
   174	                        .get(&id)
   175	                        .is_some_and(|previous| previous.member != owner)
   176	                    {
   177	                        return Err(invalid(
   178	                            "discovery registrant disagrees with retained declaration ownership",
   179	                        ));
   180	                    }
   181	                    if !scope.contains(&owner) {
   182	                        exclusions.insert(id, owner);
   183	                        continue;
   184	                    }
   185	                    let (record, pages) = self.source.hydrate(id).await?;
   186	                    receipts.extend(pages);
   187	                    match record {
   188	                        Some(record) => {
   189	                            if record.member != owner || record.declaration.id() != id {
   190	                                return Err(invalid(
   191	                                    "hydration ownership or declaration identity disagrees with discovery",
   192	                                ));
   193	                            }
   194	                            merge_record(&mut declarations, record)?;
   195	                        }
   196	                        None => omissions.push(id),
   197	                    }
   198	                }
   199	            }
   200	            DeclarationSyncMode::Reconcile => {
   201	                let mut observed = BTreeSet::new();
   202	                for member in scope {
   203	                    let (records, pages) = self.source.capture_member(*member).await?;
   204	                    receipts.extend(pages);
   205	                    for record in records {
   206	                        if record.member != *member || !observed.insert(record.declaration.id()) {
   207	                            return Err(invalid(
   208	                                "complete capture has mismatched ownership or duplicate declaration IDs",
   209	                            ));
   210	                        }
   211	                        merge_record(&mut declarations, record)?;
   212	                    }
   213	                }
   214	                omissions.extend(
   215	                    declarations
   216	                        .keys()
   217	                        .filter(|id| !observed.contains(id))
   218	                        .copied(),
   219	                );
   220	            }
   221	        }
   222	        Ok(AcquiredDeclarations {
   223	            declarations,
   224	            receipts,
   225	            exclusions,
   226	            omissions,
   227	        })
